 self.postMessage({type:'progress',event:{message:'Checking movie sections'}});importScripts('./movie-edit-plan.js','./usm-writer.js','./native-adx.js','./hca-metadata.js');const plan=ForgeMovieEditPlan.plan(data);for(const clip of plan.clips)if(plan.audio&&clip.audio){if(clip.audioKind==='hca')ForgeHcaMetadata.inspect(clip.audio);else ForgeUsmWriter.inspectAdx({kind:'adx',data:clip.audio});}
