 for(const clip of plan.clips){const video='v'+clip.index+'.input';core.FS.writeFile(video,clip.video);args.push('-r',clip.sourceRate.n+'/'+clip.sourceRate.d,'-f',formats[clip.kind],'-i',video);const mapping={video:input++};if(plan.audio&&!plan.preserveAudio&&clip.audio){const audio='a'+clip.index+'.wav';if(clip.audioKind==='hca'){const source='source'+clip.index+'.hca',prepared=ForgeHcaMetadata.prepare(clip.audio),info=prepared.info;core.FS.writeFile(source,prepared.data);const decoded=core.exec('-hide_banner','-loglevel','error','-nostdin','-threads','1','-f','hca','-i',source,'-af',ForgeHcaMetadata.filters(info),'-c:a','pcm_s16le','-f','wav','-fs',String(ForgeMovieEditPlan.MAX_BYTES),'-y',audio);core.reset();core.FS.unlink(source);if(decoded!==0)throw Error('This HCA movie sound could not be prepared. '+logs.slice(-3).join(' '));}else core.FS.writeFile(audio,ForgeNativeAdx.pcmToWav(ForgeNativeAdx.decodeADX(clip.audio)));args.push('-f','wav','-i',audio);mapping.audio=input++;}inputs.push(mapping);}
 args.push('-filter_complex_threads','1','-filter_complex',ForgeMovieEditPlan.filters(plan,inputs),'-map','[vout]','-an','-frames:v',String(plan.frames),'-threads','1','-c:v','rawvideo','-pix_fmt','yuv420p','-f','rawvideo','-y','/edited.raw');if(plan.audio&&!plan.preserveAudio)args.push('-map','[aout]','-vn','-threads','1','-c:a','pcm_s16le','-ar','48000','-ac','2','-f','s16le','-y','/edited.pcm');
